// Gate, scrub, and batch the pulled exchanges. Progress is tracked by the
// watermark (max tc_id already in sparky_segments), so re-running this
// workflow always continues where the last run stopped.
const pull = $('Pull exchanges (legacy)').all().map(i => i.json).filter(r => r && r.tc_id != null);

const STATIC_NAMES = ['Debbie','Debby','Cindy','Brian','Dode','Franklin','Fred','Christine','Allison','Patty','Pierce','Belinda','Belle','Stella','Bryan','Jessica','Tom','Todd','Bobby','Daniel','Dedrick','Robert','Kate','Henry','Johnny','Amanda','Matthew','Michael','Marquita','Charles','Daud','Desiree'];

function namesFromTitle(title) {
  const out = [];
  if (!title) return out;
  for (const m of String(title).matchAll(/\(([^)]{2,40})\)/g)) out.push(m[1]);
  const w = String(title).match(/ with ([A-Z][\w'.-]+(?: [A-Z][\w'.-]+)*)/);
  if (w) out.push(w[1]);
  const toks = [];
  for (const full of out) for (const t of full.split(/[\s,]+/)) if (/^[A-Z][a-z'’-]{2,}$/.test(t)) toks.push(t);
  return toks;
}

function scrub(text, names) {
  if (!text) return text || null;
  let s = String(text);
  for (const n of names) {
    const esc = n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    s = s.replace(new RegExp('\\b' + esc + "(?:'s)?\\b", 'g'), '[name]');
  }
  return s;
}

const ACK = /^(ok(ay)?|yes|yeah|yep|yup|no|nope|right|correct|sure|for sure|exactly|absolutely|thank(s| you).{0,15}|sounds good|got it|mm+|hm+|uh huh)[.!?\s]*$/i;
const OPS = /\b(zoom|log ?(in|out)|password|screen ?shar\w*|refresh (the|your) screen|browser|the link|click (the|on)|enroll\w*|onboard\w*|grant|spreadsheet|dashboard|time ?sheet|invoice)\b/i;

const rows = [];
let skipped_ack = 0, skipped_ops = 0;
for (const r of pull) {
  const client = (r.client_message || '').trim();
  const coach = (r.coach_message || '').trim();
  if (ACK.test(client)) { skipped_ack++; continue; }
  if (OPS.test(client) || OPS.test(coach)) { skipped_ops++; continue; }
  const names = [...new Set([...namesFromTitle(r.title), ...STATIC_NAMES])];
  const withMatch = (r.title || '').match(/ with ([A-Z][\w'.-]+)/);
  const coachName = r.session_kind === 'adi_deep_dive' ? 'Adi Jaffe' : (withMatch ? withMatch[1] : null);
  rows.push({
    text: scrub(client, names),
    metadata: {
      coach_message: scrub(coach, names),
      ideal_response: scrub(r.ideal_response, names),
      conversation_note: scrub(r.conversation_note, names),
      client_state: r.client_state || null,
      response_type: r.response_type || null,
      interaction_type: r.interaction_type || null,
      tagged_techniques: r.tagged_techniques || null,
      source: 'ingestion_v2',
      tc_id: String(r.tc_id),
      transcript_id: r.transcript_id,
      session_kind: r.session_kind,
      coach: coachName,
      session_date: r.session_date,
    },
  });
}

const BATCH = 50;
const out = [];
for (let i = 0; i < rows.length; i += BATCH) {
  const slice = rows.slice(i, i + BATCH);
  out.push({ json: {
    texts: slice.map(x => x.text),
    rows: slice,
    batch_index: out.length,
    pulled: pull.length,
    total_new: rows.length,
    skipped_ack, skipped_ops,
  } });
}
if (!out.length) out.push({ json: { texts: [], rows: [], batch_index: 0, pulled: pull.length, total_new: 0, skipped_ack, skipped_ops } });
return out;

// One INSERT statement per embed batch, paired positionally.
// Rounding to 6 decimals ~halves memory with no practical similarity loss.
const prep = $('Prepare batches').all().map(i => i.json).filter(b => b.texts && b.texts.length);
const embed = $json;
const idx = $itemIndex;
const rows = prep[idx] ? prep[idx].rows : [];
const data = (embed && embed.data) || [];
const values = [];
for (let i = 0; i < rows.length; i++) {
  if (!data[i] || !data[i].embedding) continue;
  const t = String(rows[i].text).replace(/'/g, "''");
  const m = JSON.stringify(rows[i].metadata).replace(/'/g, "''");
  const v = '[' + data[i].embedding.map(x => Math.round(x * 1e6) / 1e6).join(',') + ']';
  values.push("('" + t + "', '" + m + "'::jsonb, '" + v + "'::vector)");
}
if (!values.length) {
  return { json: { insert_sql: 'select 0 as inserted;', rows_in_batch: 0, batch: idx } };
}
return { json: {
  insert_sql: 'insert into sparky_segments (text, metadata, embedding) values ' + values.join(',') + ';',
  rows_in_batch: values.length,
  batch: idx,
} };

const batches = $('Build insert SQL').all().map(i => i.json);
const prep = $('Prepare batches').first().json;
const inserted = batches.reduce((s, b) => s + (b.rows_in_batch || 0), 0);
return [{ json: {
  pulled_this_run: prep.pulled,
  inserted_rows: inserted,
  skipped_filler_keys: prep.skipped_ack,
  skipped_ops_content: prep.skipped_ops,
  note: inserted > 0
    ? 'More may remain — click Execute workflow again. Each run continues where the last stopped.'
    : 'Nothing new pulled — group-tier ingestion is complete.',
} }];
